@push('scripts')<script>document.getElementById('photo').addEventListener('change', function(e) { const file = e.target.files[0]; if (file) { const reader = new FileReader(); reader.onload = function(event) { const preview = document.getElementById('profilePhotoPreview'); if (preview.tagName === 'DIV') { const img = document.createElement('img'); img.src = event.target.result; img.className = 'rounded-circle w-24 h-24 object-cover mx-auto mb-3'; preview.parentNode.replaceChild(img, preview); img.id = 'profilePhotoPreview'; } else { preview.src = event.target.result; } }; reader.readAsDataURL(file); } });</script>@endpush
